#!/bin/bash
# L3a print-gap closure axcheck for pilot 72-M1 (lane A1, 2026-11-17): full-coverage
# stage of P72M1T3.lean (the 5 hermPart-family theorems with no direct print in
# l3a-run6-GREEN.log) + its sibling stages, run on the WARM 72-M1 route (app
# `crossmath-probe` via pilot72m1_probe.py — dependency-order per-file .olean +
# LEAN_PATH, so AxT3 imports the AxT2/AxT1 stages). Generated by make_axcheck72m1.py
# (TARGETS extended with T3 2026-11-17); stage files must already exist (gen dir).
# MODAL_USER=doz default (doz CLI, no sudo). Log: logs/axcheck-l3a-run1.log.
#
#   research/pilots/72-M1/run_axcheck72m1_l3a.sh <gen-dir> <log-name>
set -euo pipefail

HERE=$(cd "$(dirname "$0")"; pwd)
STAGE=/tmp/crossmath-ax72m1-l3a-stage
MODAL_USER=${MODAL_USER:-doz}
MODAL_BIN=/home/doz/dozenv/bin/modal

GENDIR=${1:?usage: run_axcheck72m1_l3a.sh <gen-dir> <log-name>}
LOG_NAME=${2:?usage: run_axcheck72m1_l3a.sh <gen-dir> <log-name>}
LOG="$HERE/logs/$LOG_NAME"

rm -rf "$STAGE"; mkdir -p "$STAGE/pilot72m1"
cp "$HERE"/pilot72m1_probe.py "$STAGE"/
cp "$GENDIR"/AxPilot72_M1_T*.lean "$STAGE"/pilot72m1/
chmod -R a+rX "$STAGE"

T3_SHA=$(sha256sum "$HERE/P72M1T3.lean" | cut -c1-16)
ST3_SHA=$(sha256sum "$GENDIR/AxPilot72_M1_T3.lean" | cut -c1-16)

{
  echo "# PROVENANCE — $LOG_NAME (lane A1 = R3-role successor, pilot 72-M1 L3a print-gap closure, $(date -u +%Y-%m-%d))"
  echo "# source of record: research/pilots/72-M1/P72M1T3.lean (sha256(16) $T3_SHA — == l3a-run6-GREEN.log:1's fe57d30b19d9, disk-verified)"
  echo "# stage: make_axcheck72m1.py gen (TARGETS +T3, 2026-11-17): AxPilot72_M1_T1 (47 prints) + _T2 (25) + _T3 (9 = FULL census incl. the"
  echo "#   5 gap decls hermPart_smul/eq_self/add/zero/sum; sibling rewrites T3->AxT2->AxT1); AxT3 sha256(16) $ST3_SHA."
  echo "# cmd: run_axcheck72m1_l3a.sh — app crossmath-probe (warm image reuse per pilot72m1_probe.py), doz Modal CLI,"
  echo "#   SPEC cpu=2.0/mem=4096 (soft) + LEAN_NUM_THREADS=2, telemetry on; mathlib ff2494ea / v4.36.0-rc2."
  echo "# expected: AxT3 stage 9 appended + 4 in-file ride-along = 13 records, all [propext, Classical.choice, Quot.sound], 0 sorryAx."
} > "$LOG"

set +e
(cd "$STAGE" && "$MODAL_BIN" run pilot72m1_probe.py --dir ./pilot72m1) 2>&1 | tee -a "$LOG"
RC=${PIPESTATUS[0]}
set -e

echo "# rc=$RC (axcheck-l3a wrapper)" >> "$LOG"
exit "$RC"
